// Writes packages/core/src/version.ts from the root package.json, which is the
// single source of truth for the version. The generated file is gitignored and
// regenerated on install, build, typecheck and test.
import { readFileSync, writeFileSync } from 'node:fs';

const rootPkg = new URL('../../../package.json', import.meta.url);
const out = new URL('../src/version.ts', import.meta.url);

const { version } = JSON.parse(readFileSync(rootPkg, 'utf8'));
if (typeof version !== 'string' || version === '') {
  throw new Error('root package.json has no version');
}

const content = `// Generated by packages/core/scripts/gen-version.mjs. Do not edit.
export const VERSION = ${JSON.stringify(version)};
`;

let current = '';
try {
  current = readFileSync(out, 'utf8');
} catch {
  // first run
}
if (current !== content) writeFileSync(out, content);
